#!/usr/bin/env bash
# Benchmark harness for cargo-mutants crate efficiency.
#
# Measures cargo-mutants' OWN cost on a fixed, deterministic workload mix.
# Fixtures are generated by this script rather than taken from the live src/
# tree, which changes as the crate is optimized and would make the workload
# drift underneath the measurements.
#
# Primary metric: total_ms = sum of the three discovery workloads (min of 3).
#   Discovery is CPU-bound and low-noise, so it is the part of the crate whose
#   efficiency can actually be measured reliably. The end-to-end run is timed
#   too, but is dominated by rustc and is therefore reported as a secondary
#   guard rather than folded into the primary metric.
#
# Correctness gates (any failure exits non-zero, so a faster-but-wrong build
# can never score well): unit tests, exact mutant counts per fixture, and the
# caught/missed breakdown of a real mutation run.

set -euo pipefail
cd "$(dirname "$0")"

export CARGO_NET_OFFLINE=1
export CARGO_TERM_COLOR=never
export RUST_BACKTRACE=0
unset RUST_LOG || true

FIXTURES="target/autoresearch-fixtures"
BIN="target/release/cargo-mutants"

echo "== build =="
cargo build --release --quiet

echo "== gate: unit tests =="
cargo test --release --bin cargo-mutants --quiet

echo "== fixtures =="
python3 - "$FIXTURES" <<'PYEOF'
import os, sys, shutil

root = sys.argv[1]
# Regenerate every run so the workload is byte-identical regardless of what
# previous iterations left behind.
if os.path.isdir(root):
    shutil.rmtree(root)
os.makedirs(root)

def crate(name, files):
    d = os.path.join(root, name)
    os.makedirs(os.path.join(d, "src"))
    with open(os.path.join(d, "Cargo.toml"), "w") as f:
        f.write('[package]\nname = "%s"\nversion = "0.0.0"\nedition = "2021"\n[workspace]\n'
                % name.replace("-", "_"))
    for rel, content in files.items():
        p = os.path.join(d, "src", rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w") as f:
            f.write(content)

# --- w1: mixed -------------------------------------------------------------
# Realistic variety over many files: binary/unary ops, match guards, calls,
# and a spread of return types that drive fnvalue.rs replacement generation.
def mixed_module(i):
    return f'''
#[derive(Debug, Clone, Default)]
pub struct Item{i} {{ pub id: i64, pub label: String, pub tags: Vec<String> }}

impl Item{i} {{
    pub fn new(id: i64, label: String) -> Self {{
        Self {{ id, label, tags: Vec::new() }}
    }}
    pub fn is_valid(&self) -> bool {{
        self.id > 0 && !self.label.is_empty()
    }}
    pub fn weight(&self, factor: i64) -> i64 {{
        self.id * factor + self.tags.len() as i64
    }}
    pub fn lookup(&self, key: &str) -> Option<&String> {{
        self.tags.iter().find(|t| t.as_str() == key)
    }}
    pub fn parse(text: &str) -> Result<Self, String> {{
        let n = text.len();
        if n == 0 {{
            return Err("empty".to_string());
        }}
        Ok(Self::new(n as i64, text.to_owned()))
    }}
    pub fn classify(&self) -> &'static str {{
        match self.id {{
            n if n < 0 => "negative",
            0 => "zero",
            n if n > 100 => "large",
            _ => "small",
        }}
    }}
    pub fn ratio(&self, other: &Item{i}) -> f64 {{
        if other.id == 0 {{ 0.0 }} else {{ self.id as f64 / other.id as f64 }}
    }}
}}

pub fn combine{i}(a: &Item{i}, b: &Item{i}) -> Vec<String> {{
    let mut out = a.tags.clone();
    out.extend(b.tags.iter().cloned());
    out
}}
'''

N_MIXED = 40
files = {f"m{i}.rs": mixed_module(i) for i in range(N_MIXED)}
files["lib.rs"] = "".join(f"pub mod m{i};\n" for i in range(N_MIXED))
crate("w1_mixed", files)

# --- w2: bigfile -----------------------------------------------------------
# One large file. Span resolution cost scales with (mutants x file size), so
# this workload is what exposes quadratic behaviour in discovery.
pad = "// " + "x" * 400 + "\n"
big = "".join(
    f'''{pad}pub struct B{i} {{ pub a: i32, pub b: String }}
impl B{i} {{
    pub fn new(a: i32, b: String) -> Self {{ Self {{ a, b }} }}
    pub fn describe(&self) -> String {{ format!("{{}}-{{}}", self.a, self.b) }}
    pub fn scaled(&self, k: i32) -> i32 {{ self.a * k }}
    pub fn valid(&self) -> bool {{ self.a > 0 && !self.b.is_empty() }}
    pub fn merge(&self, o: &B{i}) -> i32 {{ self.a + o.a }}
}}
''' for i in range(400)
)
crate("w2_bigfile", {"lib.rs": big})

# --- w3: manyfiles ---------------------------------------------------------
# Many tiny modules: per-file overhead (read, syn parse, mod resolution, AST
# teardown) with very little per-file mutation work.
N_MANY = 200
small = {f"s{i}.rs": (f"pub fn a{i}(x: i32) -> i32 {{ x + 1 }}\n"
                      f"pub fn b{i}(x: i32) -> bool {{ x > 0 }}\n")
         for i in range(N_MANY)}
small["lib.rs"] = "".join(f"pub mod s{i};\n" for i in range(N_MANY))
crate("w3_manyfiles", small)

# --- w4: end-to-end --------------------------------------------------------
# Dependency-free crate that builds and tests fast, so a real mutation run
# exercises the lab loop, build-dir copy, subprocess wait and outcome
# recording without rustc completely swamping it. Deliberately leaves one
# mutant uncaught so both the caught and missed paths are exercised.
e2e = '''
pub fn add(a: i32, b: i32) -> i32 { a + b }
pub fn mul(a: i32, b: i32) -> i32 { a * b }
pub fn is_even(n: i32) -> bool { n % 2 == 0 }
pub fn max_of(a: i32, b: i32) -> i32 { if a > b { a } else { b } }

#[cfg(test)]
mod tests {
    use super::*;
    #[test] fn t_add() { assert_eq!(add(2, 3), 5); assert_eq!(add(-1, 1), 0); }
    #[test] fn t_mul() { assert_eq!(mul(2, 3), 6); assert_eq!(mul(0, 5), 0); }
    #[test] fn t_even() { assert!(is_even(2)); assert!(!is_even(3)); }
    #[test] fn t_max() { assert_eq!(max_of(2, 3), 3); assert_eq!(max_of(5, 1), 5); }
}
'''
crate("w4_e2e", {"lib.rs": e2e})
print("fixtures generated")
PYEOF

echo "== workloads =="
python3 - "$BIN" "$FIXTURES" <<'PYEOF'
import json, os, statistics, subprocess, sys, time

BIN = os.path.abspath(sys.argv[1])
FIX = sys.argv[2]

# Expected discovery output per fixture. These are properties of the generated
# fixtures; a change means mutants were lost or invented, which invalidates any
# speedup that came with it.
EXPECT_MUTANTS = {"w1_mixed": 2040, "w2_bigfile": 7600, "w3_manyfiles": 2000}
EXPECT_E2E = {"outcomes": 24, "caught": 22, "missed": 1}
# 21 reps, not a handful: the many-small-files workload spawns one thread per
# file, and its wall time is broad and right-skewed (measured spread ~37-46 ms
# for one fixed binary). A min-of-5 on that distribution does not converge and
# reports differences between builds that are really just draws from the same
# distribution. 21 reps costs ~3 s and makes the minimum stable.
REPS = 21

def run(args, env=None):
    return subprocess.run(args, capture_output=True, text=True, env=env)

def timed(args):
    """Return (min, median) wall time in ms over REPS runs, and the last stdout.

    The minimum is the primary estimator: it is the run least perturbed by
    unrelated load. The median is reported alongside it only so that a run
    whose distribution has shifted (a genuinely slower build) can be told
    apart from one that merely drew a lucky minimum."""
    times, out = [], None
    for _ in range(REPS):
        t = time.perf_counter()
        r = run(args)
        dt = (time.perf_counter() - t) * 1000.0
        if r.returncode != 0:
            sys.stderr.write("workload failed: %s\n%s\n%s\n"
                             % (args, r.stdout[-2000:], r.stderr[-2000:]))
            sys.exit(1)
        times.append(dt)
        out = r.stdout
    times.sort()
    return times[0], statistics.median(times), out

results, medians, counts, errs = {}, {}, {}, []

for key, name in (("list_mixed_ms", "w1_mixed"),
                  ("list_bigfile_ms", "w2_bigfile"),
                  ("list_manyfiles_ms", "w3_manyfiles")):
    ms, med, out = timed([BIN, "mutants", "--list", "-d", os.path.join(FIX, name)])
    results[key] = ms
    medians[key] = med
    counts[name] = len([l for l in out.splitlines() if l.strip()])
    print(f"  {name:14s} min={ms:8.1f} ms  median={med:8.1f} ms   mutants={counts[name]}")

# End-to-end. --jobs 1 keeps scheduling deterministic.
e2e_dir = os.path.join(FIX, "w4_e2e")
t = time.perf_counter()
r = run([BIN, "mutants", "-d", e2e_dir, "--jobs", "1", "--no-times"])
e2e_ms = (time.perf_counter() - t) * 1000.0
# Exit code 2 is ExitCode::FoundProblems: the fixture deliberately leaves one
# mutant uncaught, so 2 is the expected success path here. Anything else is a
# real failure. The caught/missed gate below is what actually pins behaviour.
if r.returncode not in (0, 2):
    sys.stderr.write("e2e run failed (exit %d):\n%s\n%s\n"
                     % (r.returncode, r.stdout[-4000:], r.stderr[-4000:]))
    sys.exit(1)

with open(os.path.join(e2e_dir, "mutants.out", "outcomes.json")) as f:
    lab = json.load(f)
got_e2e = {"outcomes": len(lab["outcomes"]),
           "caught": lab.get("caught", 0),
           "missed": lab.get("missed", 0)}
print(f"  {'w4_e2e':14s} {e2e_ms:9.1f} ms   {got_e2e}")

# --- correctness gates -----------------------------------------------------
for name, want in EXPECT_MUTANTS.items():
    if counts[name] != want:
        errs.append(f"{name}: expected {want} mutants, got {counts[name]}")
for k, want in EXPECT_E2E.items():
    if got_e2e[k] != want:
        errs.append(f"w4_e2e {k}: expected {want}, got {got_e2e[k]}")
if errs:
    sys.stderr.write("CORRECTNESS FAILURE:\n  " + "\n  ".join(errs) + "\n")
    sys.exit(1)

# --- cargo subprocess count ------------------------------------------------
# Exact integer, no timing noise. Tracks redundant cargo invocations at
# startup. Measured in a separate untimed run so the shim cannot perturb the
# numbers above.
# Absolute paths are required: cargo-mutants runs cargo with the tree under
# test as cwd, so a relative $CARGO would not resolve there.
shim_dir = os.path.abspath(os.path.join(FIX, "shim"))
os.makedirs(shim_dir, exist_ok=True)
log = os.path.join(shim_dir, "log")
real = subprocess.run(["bash", "-lc", "command -v cargo"],
                      capture_output=True, text=True).stdout.strip()
shim = os.path.join(shim_dir, "cargo")
with open(shim, "w") as f:
    f.write('#!/bin/sh\necho "$@" >> "%s"\nexec "%s" "$@"\n' % (log, real))
os.chmod(shim, 0o755)
if os.path.exists(log):
    os.remove(log)
env = dict(os.environ, CARGO=shim, PATH=shim_dir + os.pathsep + os.environ["PATH"])
run([BIN, "mutants", "--list", "-d", os.path.join(FIX, "w1_mixed")], env=env)
spawns = sum(1 for _ in open(log)) if os.path.exists(log) else 0
print(f"  cargo spawns per discovery run: {spawns}")

total = results["list_mixed_ms"] + results["list_bigfile_ms"] + results["list_manyfiles_ms"]
total_median = sum(medians.values())
print()
print("METRIC total_ms=%.1f" % total)
print("METRIC total_median_ms=%.1f" % total_median)
for k in ("list_mixed_ms", "list_bigfile_ms", "list_manyfiles_ms"):
    print("METRIC %s=%.1f" % (k, results[k]))
print("METRIC e2e_ms=%.1f" % e2e_ms)
print("METRIC cargo_spawns=%d" % spawns)
print("METRIC mutants_total=%d" % sum(counts.values()))
PYEOF
